export const WEB_MARKDOWN_JS = String.raw`
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function md(value){let s=esc(value).replace(/@@CODE\d+@@/g,''),blocks=[],tick=String.fromCharCode(96);s=s.replace(new RegExp(tick+'{3}(?:\\w+)?\\n?([\\s\\S]*?)'+tick+'{3}','g'),(_,x)=>{blocks.push('<pre><code>'+x+'</code></pre>');return '@@CODE'+(blocks.length-1)+'@@'});s=s.replace(/^(?:[-*+] [^\n]*(?:\n|$))+/gm,items=>{let trailing=items.endsWith('\n'),lines=items.split('\n');if(trailing)lines.pop();return '<ul>'+lines.map(item=>'<li>'+item.slice(2)+'</li>').join('')+'</ul>'+(trailing?'\n':'')}).replace(/^-# (.*)$/gm,'<small class="subtext">$1</small>').replace(new RegExp(tick+'([^'+tick+']+)'+tick,'g'),'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/__([^_]+)__/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/^###? (.+)$/gm,'<h3>$1</h3>').replace(/^# (.+)$/gm,'<h2>$1</h2>').replace(/^&gt; (.+)$/gm,'<blockquote>$1</blockquote>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/(^|\s)(https?:\/\/[^\s<]+)/g,'$1<a href="$2" target="_blank" rel="noopener noreferrer">$2</a>').replace(/\n/g,'<br>');return s.replace(/@@CODE(\d+)@@/g,(_,i)=>blocks[Number(i)])}
`

