async function sendPrompt(prompt,name,settings){if(state.starting.has(name))return;clearTimeout(state.pollTimer);state.starting.add(name);renderRunControls();let pending,runId,failed=false;try{if(state.runs.has(name))await cancelRun(name,true);if(name===state.sessionName){state.historySignatures.delete(name);$('#messages .empty')?.remove();message('user',prompt);pending=message('assistant','');pending.querySelector('.body').innerHTML='<span class="status">Starting assistant...</span>'}let body={prompt,sessionName:name,...settings},r=await api('/api/chat',{method:'POST',body:JSON.stringify(body)}),reader=r.body.getReader(),decoder=new TextDecoder(),buffer='';while(true){let {done,value}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});let lines=buffer.split('\n');buffer=lines.pop()||'';for(let line of lines){if(!line)continue;let update=JSON.parse(line);if(update.runId){runId=update.runId;state.runs.set(name,{id:runId,local:true});state.starting.delete(name);if(pending)pending.dataset.runId=runId;renderRunControls()}let target=runId&&name===state.sessionName&&state.runs.get(name)?.id===runId?(runMessage(runId)||pending):null;if(target&&update.payload)target.querySelector('.body').innerHTML=payload(update.payload);if(target&&update.error)target.querySelector('.body').innerHTML='<span class="status error">'+esc(update.error)+'</span>'}if(done)break}}catch(err){failed=true;let target=runId?runMessage(runId):pending;if(name===state.sessionName&&target?.isConnected)target.querySelector('.body').innerHTML='<span class="status error">'+esc(err.message)+'</span>'}finally{state.starting.delete(name);if(runId&&state.runs.get(name)?.id===runId)state.runs.delete(name);let target=runId&&runMessage(runId);if(target)delete target.dataset.runId;if(pending)delete pending.dataset.runId;if(failed&&name===state.sessionName)await history(name,state.loadVersion).catch(()=>{});if(name===state.sessionName)scheduleSessionPoll();renderRunControls()}}
$('#cancel-run').onclick=async()=>{try{await cancelRun()}catch(err){window.alert(err.message)}};
$('#composer').addEventListener('submit',async e=>{e.preventDefault();let name=state.sessionName;if(state.starting.has(name))return;let prompt=$('#prompt').value.trim();if(!prompt)return;let settings={model:$('#model-select').value.trim(),effort:$('#effort').value,maxTokens:Number($('#max-tokens').value)};$('#prompt').value='';$('#prompt').style.height='auto';if(prompt==='/clear'){try{state.starting.add(name);renderRunControls();await api('/api/chat/clear',{method:'POST',body:JSON.stringify({sessionName:name})});state.runs.delete(name);await history(name,state.loadVersion)}catch(err){$('#messages').innerHTML='<div class="empty error">'+esc(err.message)+'</div>'}finally{state.starting.delete(name);renderRunControls()}return}await sendPrompt(prompt,name,settings)});
$('#prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#composer').requestSubmit()}});$('#prompt').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,180)+'px'});$('#login').onclick=()=>location.href='/auth/login';
$('#admin-prompt').onclick=openPromptSettings;$('#mobile-settings').onclick=openPromptSettings;$('#chat-nav').onclick=()=>showWorkspaceView('chat');$('#prompt-back').onclick=()=>showWorkspaceView('chat');window.addEventListener('hashchange',()=>{if(location.hash!=='#agent-settings'&&!$('#prompt-settings-view').hidden)showWorkspaceView('chat')});
