$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();let f=e.target,data=Object.fromEntries(new FormData(f));data.enabled=f.elements.enabled.checked;data.automaticLogin=f.elements.automaticLogin.checked;try{let r=await api('/api/admin/oidc',{method:'PUT',body:JSON.stringify(data)}),saved=await r.json();$('#settings-status').textContent='Saved';$('#secret-state').textContent=saved.hasClientSecret?'A secret is stored.':'';if(state.session.oidcSetupRequired)await session()}catch(err){$('#settings-status').textContent=err.message}});session().catch(e=>$('#auth-error').textContent=e.message);
